INSERT INTO `wp_wc_admin_notes` VALUES (1,'wc-refund-returns-page','info','en_US','Setup a Refund and Returns Policy page to boost your store\'s credibility.','We have created a sample draft Refund and Returns Policy page for you. Please have a look and update it to fit your store.','{}','unactioned','woocommerce-core','2026-10-11 20:10:27',NULL,0,'plain','',0,1,'info'),(2,'wc-admin-order-withdrawal-feature','info','en_US','Enable order withdrawal for EU regulatory requirements','Stores selling to EU countries may need to offer customers a way to withdraw from qualifying orders. Review how to enable the order withdrawal feature in the Advanced settings.','{}','unactioned','woocommerce-admin','2026-10-11 20:12:14',NULL,0,'plain','',0,1,'info'),(3,'ppcp-recaptcha-protection-note12','info','en_US','Fraud protection is now required — enable today','Card networks like Visa, Mastercard and American Express now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.','{}','unactioned','woocommerce-paypal-payments','2026-10-11 20:17:36',NULL,0,'plain','',0,1,'info');
